<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Brand; use Illuminate\Http\Request; use Illuminate\Support\Str;
class BrandController extends Controller { public function index(){return view('admin.brands.index',['brands'=>Brand::latest()->paginate(20)]);} public function create(){return view('admin.brands.form',['brand'=>new Brand]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','is_active'=>'nullable']); Brand::create(['name'=>$d['name'],'slug'=>Str::slug($d['name']),'is_active'=>$r->boolean('is_active')]); return redirect()->route('admin.brands.index')->with('success','Marka eklendi.');} public function edit(Brand $brand){return view('admin.brands.form',compact('brand'));} public function update(Request $r, Brand $brand){$d=$r->validate(['name'=>'required|max:255','is_active'=>'nullable']); $brand->update(['name'=>$d['name'],'slug'=>Str::slug($d['name']),'is_active'=>$r->boolean('is_active')]); return redirect()->route('admin.brands.index')->with('success','Marka güncellendi.');} public function destroy(Brand $brand){$brand->delete(); return back()->with('success','Marka silindi.');} public function show(Brand $brand){ return redirect()->route('admin.brands.edit',$brand); } }
